/bin/zsh -lc "python3 - <<'PY'
import json,pathlib
for name in ['policy.json','coordination.json','source.json','result-schema.json']:
 p=pathlib.Path(name); s=p.read_text(); d=json.loads(s)
 print(name,'characters',len(s),'type',type(d).__name__)
 if name"'!='"'source.json': print(s)
 else:
  print('keys',list(d) if isinstance(d,dict) else '')
  if isinstance(d,dict):
   for k,v in d.items():
    print(k,type(v).__name__,len(v) if isinstance(v,(list,str,dict)) else v)
  else:
   for i,a in enumerate(d): print(i,{k:(len(v) if k.endswith('xml') else v) for k,v in a.items()})
PY"

